fn set_autostart(app: AppHandle, enabled: bool) -> Result<(), String> {
    let mgr = app.autolaunch();
    if enabled {
        mgr.enable().map_err(|e| e.to_string())
    } else {
        mgr.disable().map_err(|e| e.to_string())
    }
}

/// Persist the API base URL into app_config_dir/config.json, which load_config
/// reads at the highest priority. Other fields are preserved.
#[tauri::command]
fn save_api_base_url(app: AppHandle, url: String) -> Result<(), String> {
    let dir = app.path().app_config_dir().map_err(|e| e.to_string())?;
    fs::create_dir_all(&dir).map_err(|e| e.to_string())?;
    let path = dir.join("config.json");
    let mut v: Value = fs::read_to_string(&path)
        .ok()
        .and_then(|s| serde_json::from_str(&s).ok())
        .unwrap_or_else(|| {
            let c = load_config(&app);
            serde_json::json!({
                "apiBaseUrl": c.api_base_url,
                "refreshIntervalMinutes": c.refresh_interval_minutes,
                "defaultSection": c.default_section,
                "itemsPerSection": c.items_per_section,
            })
        });
    v["apiBaseUrl"] = Value::String(url.trim_end_matches('/').to_string());
    let out = serde_json::to_string_pretty(&v).map_err(|e| e.to_string())?;
    fs::write(&path, out).map_err(|e| e.to_string())
}

