els.settingsSave.addEventListener("click", async () => {
  const url = els.settingsUrl.value.trim().replace(/\/$/, "");
  if (!url) return;
  state.config.apiBaseUrl = url;
  try {
    if (TAURI?.core?.invoke) {
      await TAURI.core.invoke("save_api_base_url", { url });
    } else {
      localStorage.setItem("widgetApiBaseUrl", url);
    }
  } catch (err) {
    console.error("save_api_base_url failed", err);
  }
  els.settingsPanel.classList.add("hidden");
  showToast("地址已更新");
  loadDigest(true);
});

